<script setup lang="ts">
import { computed } from 'vue';import ChartBase from './ChartBase.vue';import type { EChartsCoreOption } from 'echarts/core';const props=withDefaults(defineProps<{labels:string[];values:number[];name?:string;height?:number|string}>(),{name:'数值',height:240});const css=(n:string)=>getComputedStyle(document.documentElement).getPropertyValue(n).trim();const option=computed<EChartsCoreOption>(()=>({grid:{left:44,right:14,top:20,bottom:34},tooltip:{trigger:'axis'},xAxis:{type:'category',data:props.labels,axisLabel:{color:css('--text-3')}},yAxis:{type:'value',splitLine:{lineStyle:{color:css('--border')}}},series:[{name:props.name,type:'bar',data:props.values,itemStyle:{color:css('--brand'),borderRadius:[5,5,0,0]},barMaxWidth:28}]}))
</script><template><ChartBase :option="option" :height="height" :empty="!values.length"/></template>
